(function () {
  'use strict';

  // SVG frames as base64 data URIs
  const F = {
    CAT1: 'data:image/svg+xml;base64,',
    CAT2: 'data:image/svg+xml;base64,',
    CAT3: 'data:image/svg+xml;base64,',
    CAT7: 'data:image/svg+xml;base64,',
    CAT8: 'data:image/svg+xml;base64,',
    MOUSE_RIGHT: 'data:image/svg+xml;base64,',
    MOUSE_LEFT:  'data:image/svg+xml;base64,',
    CAT9: 'data:image/svg+xml;base64,',
    DUST1: 'data:image/svg+xml;base64,',
    DUST2: 'data:image/svg+xml;base64,',
    DUST3: 'data:image/svg+xml;base64,',
    DUST4: 'data:image/svg+xml;base64,',
  };

  // ── Inject CSS ──────────────────────────────────────────────────────────────
  const style = document.createElement('style');
  style.textContent = `
    #__icat-wrap {
      position: fixed; width: 55px; height: 36.7px;
      transform-origin: center center; transition: none;
      will-change: transform, left, top;
      pointer-events: none; overflow: visible; z-index: 99998;
    }
    #__icat-frame {
      display: block; position: absolute; bottom: 0; left: 50%;
      transform: translateX(-50%); width: 55px; height: auto;
      user-select: none; -webkit-user-drag: none;
    }
    #__icat-dust {
      position: fixed; width: 75px; height: 75px;
      margin-left: -37.5px; margin-top: -37.5px;
      pointer-events: none; display: none; z-index: 99997;
    }
    #__icat-dust img { display: block; width: 75px; height: 75px; user-select: none; }
    #__icat-cursor {
      position: fixed; pointer-events: none; display: none; z-index: 99999;
      width: 55px; height: auto;
    }
    body.__icat-dragging, body.__icat-dragging * { cursor: none !important; }
  `;
  document.head.appendChild(style);

  // ── Inject HTML ─────────────────────────────────────────────────────────────
  const wrap = document.createElement('div'); wrap.id = '__icat-wrap';
  const img  = document.createElement('img'); img.id = '__icat-frame'; img.alt = '';
  wrap.appendChild(img); document.body.appendChild(wrap);

  const dustWrap = document.createElement('div'); dustWrap.id = '__icat-dust';
  const dustImg  = document.createElement('img'); dustImg.alt = '';
  dustWrap.appendChild(dustImg); document.body.appendChild(dustWrap);

  const fakeCursor = document.createElement('img'); fakeCursor.id = '__icat-cursor'; fakeCursor.alt = '';
  document.body.appendChild(fakeCursor);

  // ── Frame sequences ─────────────────────────────────────────────────────────
  const FRAMES = {
    idle:     [F.CAT3],
    active:   [F.CAT3, F.CAT1, F.CAT2, F.CAT1],
    ambush:   [F.CAT7, F.CAT9],
    pounce:   [F.CAT8],
    dragging: [F.CAT7],
  };
  const DUST_SEQ = [
    { src: F.DUST1, count: 3 },
    { src: F.DUST2, count: 2 },
    { src: F.DUST3, count: 1 },
    { src: F.DUST4, count: 1 },
  ];
  const FRAME_DATA = {
    [F.CAT1]: { w: 55,   h: null },
    [F.CAT2]: { w: 55,   h: null },
    [F.CAT3]: { w: 55,   h: null },
    [F.CAT7]: { w: 55,   h: null },
    [F.CAT8]: { w: 36.7, h: 27.5 },
    [F.CAT9]: { w: 55,   h: null },
  };

  // ── Config ──────────────────────────────────────────────────────────────────
  const CFG = {
    idleMin:1200, idleMax:2400, activeFps:400, ambushFps:1200,
    mouseIdleMs:1400, ambushRadius:350, pounceHalfW:50, pounceHalfH:200,
    jumpStillMs:1500, jumpStillPx:12,
    dragLerp:0.055, dragOffsetX:27.5, dragOffsetY:13.75,
    facingCommitMs:500, deadZonePx:30,
    shakeReversals:3, shakeWindowMs:600, shakeMinPx:15,
    dustFrameMs:70,
  };

  // ── State ───────────────────────────────────────────────────────────────────
  let catX = window.innerWidth/2, catY = window.innerHeight/2;
  let mX = catX, mY = catY, lastMoveTime = performance.now();
  let state='idle', frameIdx=0, frameMs=0, frameDur=rnd(CFG.idleMin,CFG.idleMax);
  let facing='right', pendingFace='right', pendingFaceSince=performance.now();
  let stillInAmbushSince=null, stillAnchorX=mX, stillAnchorY=mY;
  let dustActive=false, dustSeqIdx=0, dustTickIdx=0, dustMs=0;
  let shakeHistory=[], dragX=0, dragY=0, lastTick=null;
  let hiddenSiteCursors=[];

  // ── Site cursor detection ────────────────────────────────────────────────────
  // Find and hide any existing custom cursor elements on the page (not ours)
  function hideSiteCursors(){
    hiddenSiteCursors=[];
    document.querySelectorAll('[id*="cursor"],[class*="cursor"],[id*="Cursor"],[class*="Cursor"]').forEach(el=>{
      if(el.id&&el.id.startsWith('__icat'))return; // skip our own elements
      const prev=el.style.display;
      el.style.setProperty('display','none','important');
      hiddenSiteCursors.push({el,prev});
    });
  }
  function restoreSiteCursors(){
    hiddenSiteCursors.forEach(({el,prev})=>el.style.display=prev||'');
    hiddenSiteCursors=[];
  }

  // ── Helpers ─────────────────────────────────────────────────────────────────
  function rnd(lo,hi){return Math.random()*(hi-lo)+lo;}
  function dist(ax,ay,bx,by){const dx=ax-bx,dy=ay-by;return Math.sqrt(dx*dx+dy*dy);}
  function frameDuration(st){
    if(st==='idle')return rnd(CFG.idleMin,CFG.idleMax);
    if(st==='active')return CFG.activeFps;
    if(st==='ambush')return CFG.ambushFps;
    return 9999999;
  }

  // ── Facing ──────────────────────────────────────────────────────────────────
  function applyWrap(){
    wrap.style.left=(catX-27.5)+'px';
    wrap.style.top=(catY-18.35)+'px';
    wrap.style.transform=facing==='left'?'scaleX(-1)':'scaleX(1)';
  }
  function commitFacing(f){facing=f;applyWrap();}
  function tickFacing(now){
    if(state==='dragging')return;
    let want=null;
    if(mX<catX-CFG.deadZonePx)want='left';
    else if(mX>catX+CFG.deadZonePx)want='right';
    if(!want){pendingFace=facing;pendingFaceSince=now;return;}
    if(want!==pendingFace){pendingFace=want;pendingFaceSince=now;return;}
    if(want!==facing&&now-pendingFaceSince>=CFG.facingCommitMs)commitFacing(want);
  }

  // ── Zones ───────────────────────────────────────────────────────────────────
  function inAmbush(){return dist(mX,mY,catX,catY)<CFG.ambushRadius;}
  function inPounce(){return Math.abs(mX-catX)<=CFG.pounceHalfW&&Math.abs(mY-catY)<=CFG.pounceHalfH;}

  // ── Dust ────────────────────────────────────────────────────────────────────
  function startDust(ox,oy){
    dustWrap.style.left=ox+'px'; dustWrap.style.top=oy+'px';
    dustWrap.style.display='block';
    dustSeqIdx=0;dustTickIdx=0;dustMs=0;dustActive=true;
    dustImg.src=DUST_SEQ[0].src;
  }
  function tickDust(dt){
    if(!dustActive)return;
    dustMs+=dt;
    if(dustMs>=CFG.dustFrameMs){
      dustMs-=CFG.dustFrameMs; dustTickIdx++;
      if(dustTickIdx>=DUST_SEQ[dustSeqIdx].count){
        dustSeqIdx++;dustTickIdx=0;
        if(dustSeqIdx>=DUST_SEQ.length){dustActive=false;dustWrap.style.display='none';return;}
        dustImg.src=DUST_SEQ[dustSeqIdx].src;
      }
    }
  }

  // ── Shake ───────────────────────────────────────────────────────────────────
  function recordShake(now,x){
    shakeHistory.push({t:now,x});
    shakeHistory=shakeHistory.filter(e=>e.t>=now-CFG.shakeWindowMs);
  }
  function countReversals(){
    if(shakeHistory.length<3)return 0;
    let rev=0,lastDir=null;
    for(let i=1;i<shakeHistory.length;i++){
      const dx=shakeHistory[i].x-shakeHistory[i-1].x;
      if(Math.abs(dx)<CFG.shakeMinPx)continue;
      const dir=dx>0?1:-1;
      if(lastDir!==null&&dir!==lastDir)rev++;
      lastDir=dir;
    }
    return rev;
  }

  // ── Drag ────────────────────────────────────────────────────────────────────
  function positionDragCursor(){
    // fakeCursor IS the mouse pointer — MOUSE_RIGHT or MOUSE_LEFT based on direction
    // hotspot: top-left of the SVG is the tip of the pointer arrow
    if(facing==='right'){
      fakeCursor.src = F.MOUSE_RIGHT;
      fakeCursor.style.left = dragX + 'px';
      fakeCursor.style.top  = dragY + 'px';
    } else {
      fakeCursor.src = F.MOUSE_LEFT;
      // MOUSE_LEFT arrow tip is at top-right, so offset left by width
      fakeCursor.style.left = (dragX - 55) + 'px';
      fakeCursor.style.top  = dragY + 'px';
    }
  }
  function tickDragging(dt){
    if(state!=='dragging')return;
    const t=1-Math.pow(1-CFG.dragLerp,dt/16);
    const nx=dragX+(mX-dragX)*t, ny=dragY+(mY-dragY)*t;
    const dx=nx-dragX;
    if(Math.abs(dx)>0.3){
      const newFacing=dx>0?'right':'left';
      if(newFacing!==facing) facing=newFacing;
    }
    dragX=nx;dragY=ny;
    positionDragCursor();
    // keep logical cat position for zone calculations
    const ox=facing==='right'?-CFG.dragOffsetX:CFG.dragOffsetX;
    catX=dragX+ox; catY=dragY-CFG.dragOffsetY;
    recordShake(performance.now(),mX);
    if(countReversals()>=CFG.shakeReversals)releaseDrag();
  }
  function releaseDrag(){
    shakeHistory=[];stillInAmbushSince=null;
    document.body.classList.remove('__icat-dragging');
    fakeCursor.style.display='none';
    restoreSiteCursors();
    wrap.style.display=''; // show cat body again at its current catX/catY
    applyWrap();
    const now=performance.now();
    const next=inAmbush()?(inPounce()?'pounce':'ambush'):(now-lastMoveTime<CFG.mouseIdleMs?'active':'idle');
    setState(next);
  }

  // ── Jump ────────────────────────────────────────────────────────────────────
  function triggerJump(){
    const ox=catX,oy=catY;
    facing=mX<catX?'left':'right';
    dragX=mX;dragY=mY;
    const offX=facing==='right'?-CFG.dragOffsetX:CFG.dragOffsetX;
    catX=dragX+offX;catY=dragY-CFG.dragOffsetY;
    // switch cursor to mouse pointer SVG
    fakeCursor.style.width='55px';
    fakeCursor.style.height='auto';
    fakeCursor.style.display='block';
    wrap.style.display='none'; // hide the cat body
    document.body.classList.add('__icat-dragging');
    hideSiteCursors();
    positionDragCursor();
    startDust(ox,oy);
    setState('dragging');
    shakeHistory=[];stillInAmbushSince=null;
  }

  // ── Jump timer ──────────────────────────────────────────────────────────────
  function tickJumpTimer(now){
    if(state!=='ambush'){stillInAmbushSince=null;return;}
    const moved=dist(mX,mY,stillAnchorX,stillAnchorY)>CFG.jumpStillPx;
    if(moved){stillInAmbushSince=now;stillAnchorX=mX;stillAnchorY=mY;}
    else if(!stillInAmbushSince){stillInAmbushSince=now;stillAnchorX=mX;stillAnchorY=mY;}
    else if(now-stillInAmbushSince>=CFG.jumpStillMs)triggerJump();
  }

  // ── State machine ────────────────────────────────────────────────────────────
  function resolveState(now){
    if(state==='dragging')return state;
    if(inAmbush())return inPounce()?'pounce':'ambush';
    return now-lastMoveTime<CFG.mouseIdleMs?'active':'idle';
  }
  function setState(next){
    if(next===state)return;
    state=next;frameMs=0;frameIdx=0;frameDur=frameDuration(state);renderFrame();
  }

  // ── Render ───────────────────────────────────────────────────────────────────
  function renderFrame(){
    if(state==='dragging')return; // cat is hidden; fake cursor handles display
    const src=FRAMES[state][frameIdx];
    const data=FRAME_DATA[src]||{w:55,h:null};
    if(img.src!==src)img.src=src;
    img.style.width=data.w+'px';
    img.style.height=data.h?data.h+'px':'auto';
    applyWrap();
  }
  function advanceFrame(){
    if(state==='pounce'||state==='dragging')return;
    frameIdx=(frameIdx+1)%FRAMES[state].length;
    frameDur=frameDuration(state);renderFrame();
  }

  // ── Main loop ────────────────────────────────────────────────────────────────
  function tick(now){
    if(!lastTick)lastTick=now;
    const dt=Math.min(now-lastTick,100);lastTick=now;
    tickFacing(now);tickDust(dt);tickJumpTimer(now);tickDragging(dt);
    setState(resolveState(now));
    frameMs+=dt;
    if(frameMs>=frameDur){frameMs-=frameDur;advanceFrame();}
    renderFrame();
    requestAnimationFrame(tick);
  }

  // ── Input ────────────────────────────────────────────────────────────────────
  window.addEventListener('mousemove',e=>{mX=e.clientX;mY=e.clientY;lastMoveTime=performance.now();});
  window.addEventListener('mouseleave',()=>{lastMoveTime=0;});

  // ── Boot ─────────────────────────────────────────────────────────────────────
  commitFacing('right');renderFrame();requestAnimationFrame(tick);
})();
